import {mountAnimation,simulations} from './learning-animations.mjs';
import {encryptStudy,decryptStudy,vaultPut,vaultList} from './offline-vault.mjs';
import {encryptedWorkspaceHTML} from './offline-workspace.mjs';
import {offlineLessonHTML} from './offline-export.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let me=null,ai=false,view='feed',feed=[],following=false,room=null,narration=null,observer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(p,b){const r=await fetch('/api'+p,{method:b===undefined?'GET':'POST',headers:b===undefined?{}:{'Content-Type':'application/json'},body:b===undefined?undefined:JSON.stringify(b)});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
async function act(fn){try{await fn();}catch(e){toast(e.message);}}
function modal(t,h){stop();$('#dialog-title').textContent=t;$('#dialog-body').innerHTML=h;$('#dialog').showModal();}$('#dialog-close').onclick=()=>$('#dialog').close();
function needed(){if(me)return true;auth();return false;}
async function refresh(){const d=await api('/me');me=d.user;ai=d.ai;$('#account-label').innerHTML=me?`${esc(me.name)}<small>${me.admin?'Reviewer account':'Your learning profile'}</small>`:'Join the conversation<small>Create your account</small>';$('.account .avatar').textContent=me?.name[0]||'M';}
function auth(){window.top.location.href='/signin-with-chatgpt?return_to=%2F';}
async function account(){if(!me)return auth();const p=await api('/profile');modal('Your learning profile',`<div class="panel"><h2>${esc(me.name)}</h2><p>${p.saved} saved lessons · ${p.followers} followers</p><p>${p.attempts.correct} correct checks from ${p.attempts.n} attempts.</p><p>Practice evidence is not a certified mastery score.</p></div><div class="button-row"><button id="packs" class="secondary">Study pack enquiries</button><button id="logout" class="secondary">Sign out</button></div>`);$('#logout').onclick=()=>act(async()=>{const r=await api('/logout',{});window.top.location.href=r.signout;});$('#packs').onclick=()=>act(payments);}
$('#account').onclick=$('#mobile-account').onclick=()=>act(account);$('#creator-open').onclick=()=>render('create');$$('[data-view]').forEach(b=>b.onclick=()=>render(b.dataset.view));$$('[data-feed]').forEach(b=>b.onclick=()=>{following=b.dataset.feed==='following';$$('[data-feed]').forEach(x=>x.classList.toggle('selected',x===b));render('feed');});$('#subject').onchange=()=>render('feed');$('#search').onchange=()=>render('feed');$$('[data-subject]').forEach(b=>b.onclick=()=>{$('#subject').value=b.dataset.subject;render('feed');});
function stop(){window.speechSynthesis?.cancel();if(narration)narration.querySelector('.listen').textContent='▶ Listen';narration=null;}
async function render(v='feed'){document.body.classList.toggle('feed-mode',v==='feed'||v==='saved');leave();stop();if(typeof tutorClock!=='undefined')clearInterval(tutorClock);observer?.disconnect();view=v;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#page-title').textContent={feed:'A little wiser, one scroll at a time.',saved:'Ideas worth coming back to.',rooms:'Good questions bring people together.',plan:'Make room for what you want to learn.',create:'Share an idea. Start a conversation.',notes:'Your course, in your pocket.',tutors:'A tutor. A clear next step.',workspace:'An idea you can work with.',vault:'Learning you can carry offline.',assembly:'Know what is coming next.',rewards:'Show up. Learn. Be recognised.',schools:'Your school life, connected.'}[v];$('#content').innerHTML='<div class="empty">Loading your next chapter…</div>';try{if(v==='feed'||v==='saved')await showFeed();else if(v==='rooms')await showRooms();else if(v==='plan')await showPlan();else if(v==='notes')await showNotes();else if(v==='tutors')await showTutoring();else if(v==='workspace')await openWorkspace(feed[0]?.id);else if(v==='vault')await showVault();else if(v==='assembly')await showAssembly();else if(v==='rewards')await showRewards();else if(v==='schools')await showSchools();else await showCreator();}catch(e){$('#content').innerHTML=`<div class="empty">${esc(e.message)}</div>`;}}
function art(l){return l.id==='mean'?'<span class="art-number">2</span><span class="art-number">4</span><span class="art-number">6</span><span class="art-symbol">→</span><span class="art-answer">4</span>':l.subject==='Economics'?'<span class="choice-art">◷</span><span class="art-symbol">⇄</span><span class="art-number">$</span>':'<span class="art-number">01</span><span class="art-symbol">→</span><span class="art-number">02</span><span class="art-symbol">→</span><span class="art-answer">✓</span>';}
async function showFeed(){observer?.disconnect();stop();clearTimeout(recallTimer);feed=await api('/feed?'+new URLSearchParams({subject:$('#subject').value,q:$('#search').value,...(view==='saved'?{saved:'1'}:{}),...(following&&view==='feed'?{following:'1'}:{})}));$('#content').innerHTML=feed.length?`<div class="feed">${feed.map(l=>`<article class="post" data-id="${esc(l.id)}"><div class="post-top"><div class="creator"><span class="avatar">${esc(l.author[0])}</span><div><strong>${esc(l.author)}</strong><small>${esc(l.recommendation||'Academic ideas, made understandable')}</small></div></div><button class="follow" data-action="follow">${l.following?'Following':'+ Follow'}</button></div><div class="post-layout"><div class="lesson-card ${['pink','blue'].includes(l.color)?l.color:''}"><div class="card-top"><span class="subject-chip">${esc(l.subject.toUpperCase())}</span><span class="duration">${l.slides.length} STEPS · LISTEN & LEARN</span></div><h2>${esc(l.title)}</h2><div class="concept-art">${l.asset?mediaArt(l):art(l)}</div><div class="card-caption"><span class="step-label">ONE CONCEPT. ONE CLEAR EXPLANATION.</span><div class="step-text">${esc(l.slides[0].text)}</div><div class="transcript">${esc(l.slides[0].narration)}</div></div><div class="card-controls"><button class="listen" data-action="listen">▶ Listen</button><button class="next" data-action="prev" aria-label="Previous step">←</button><button class="next" data-action="next">Next step →</button></div><div class="segments">${l.slides.map((s,i)=>`<span class="${i===0?'done':''}"></span>`).join('')}</div></div><div class="actions">${[['love','♡',l.likes,l.loved],['comments','☏',l.comments],['save','▱','Save',l.saved],['share','↗','Share'],['ask','✧','Ask AI']].map(([a,s,t,on])=>`<button data-action="${a}" class="${on?'on':''}" aria-label="${a}"><span>${s}</span><small>${t}</small></button>`).join('')}</div></div><div class="post-bottom">${esc(l.objective)}<br><button data-action="quiz">Try a quick check ↗</button> · <button data-action="source">Sources & corrections</button> · <button data-action="workspace">Study workspace</button>${simulations[l.id]?' · <button data-action="animation">Explore animation</button>':''} · <button data-action="journey">Explore this idea</button> · <button data-action="explain">My explanation</button> · <button data-action="download">Download</button>${l.noteId?'<button data-action="original"> · Original notes</button>':''}</div></article>`).join('')}</div>`:'<div class="empty">No lessons here yet.<br>Follow a creator or explore another subject.</div>';
$$('.post').forEach(el=>{el.step=0;el.onclick=e=>{const b=e.target.closest('[data-action]');if(b)act(()=>post(el,b.dataset.action));};});observer=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting){if(narration===e.target)stop();e.target.querySelectorAll('video,audio').forEach(v=>v.pause());}else{activePost=e.target;trackStudy(e.target);if(autoVoice&&!$('#dialog').open)speak(e.target,feed.find(l=>l.id===e.target.dataset.id));if(!lowData)e.target.querySelector('video')?.play().catch(()=>{});}}),{threshold:.65});$$('.post').forEach(e=>observer.observe(e));const target=decodeURIComponent(location.hash.slice(1));$$('.post').find(e=>e.dataset.id===target)?.scrollIntoView();}
function step(el,l,i){el.step=(i+l.slides.length)%l.slides.length;try{localStorage.setItem('sm-resume:'+(me?.id||'visitor'),JSON.stringify({id:l.id,title:l.title,step:el.step}));}catch{}el.querySelector('.step-text').textContent=l.slides[el.step].text;el.querySelector('.transcript').textContent=l.slides[el.step].narration;[...el.querySelectorAll('.segments span')].forEach((s,i)=>s.classList.toggle('done',i<=el.step));}
function speak(el,l){if(!('speechSynthesis'in window))return toast('Voice is not supported here. Use the transcript.');stop();narration=el;el.querySelector('.listen').textContent='Ⅱ Pause';const u=new SpeechSynthesisUtterance(l.slides[el.step].narration);u.rate=.94;u.onend=()=>{if(narration!==el)return;if(el.step+1<l.slides.length){step(el,l,el.step+1);speak(el,l);}else stop();};u.onerror=()=>stop();speechSynthesis.speak(u);}
async function post(el,a){const l=feed.find(l=>l.id===el.dataset.id);if(a==='listen'){autoVoice=true;$('#autovoice').textContent='Voice on';return narration===el?stop():speak(el,l);}if(a==='next'||a==='prev'){stop();return step(el,l,el.step+(a==='next'?1:-1));}if(a==='share'){const url=location.origin+'/social.html#'+encodeURIComponent(l.id);if(navigator.share)await navigator.share({title:l.title,url});else{await navigator.clipboard.writeText(url);toast('Lesson link copied');}return;}
if(a==='animation'){openLearningAnimation(l.id);return;}if(a==='workspace'){await openWorkspace(l.id);return;}if(a==='journey'){if(!needed())return;await lessonJourney(l,el);return;}if(a==='explain'){if(!needed())return;await render('create');editor({parentId:l.id,title:('My explanation: '+l.title).slice(0,100),subject:l.subject,objective:l.objective,slides:[{text:'The idea in my own words',narration:''}],example:'',question:'',options:['',''],answer:0,rationale:'',source:'Based on Study Media lesson: '+l.title+'\n\n'+l.source});return;}if(a==='download'){if(!needed())return;const full=await api(`/lessons/${l.id}/download`);saveFile(offlineLessonHTML(full),(l.title.replace(/[^a-z0-9]+/gi,'-').slice(0,70)||'lesson')+'.html','text/html');return;}if(a==='loadmedia'){el.querySelector('.concept-art').innerHTML=loadedMediaArt(l);return;}if(a==='original'){if(!needed())return;try{const note=await api('/notes/'+l.noteId);modal(note.title,'<div class="answer-text">'+esc(note.body)+'</div>')}catch{modal('Source excerpt','<p>Full notes are private to their uploader. This lesson includes the following excerpt:</p><div class="answer-text">'+esc(l.source)+'</div>')}return;}if(a==='source'){modal('Sources and corrections',`<p class="answer-text">${esc(l.source)}</p><p class="notice">Source information is not a guarantee of verification.</p><form id="correction" class="form"><label>Suggest a correction<textarea name="text" maxlength="2000" required></textarea></label><button class="primary">Send correction</button></form>`);$('#correction').onsubmit=e=>{e.preventDefault();if(!needed())return;act(async()=>{await api(`/lessons/${l.id}/report`,{text:new FormData(e.target).get('text')});$('#dialog').close();toast('Correction sent for review');});};return;}
if(!needed())return;if(a==='love'||a==='save'){const key=a==='love'?'loved':'saved';await api(`/lessons/${l.id}/reaction`,{kind:a,active:!l[key]});l[key]=!l[key];const b=el.querySelector(`[data-action="${a}"]`);b.classList.toggle('on',l[key]);if(a==='love'){l.likes+=l.loved?1:-1;b.querySelector('small').textContent=l.likes;}return;}
if(a==='follow'){await api('/follow',{target:l.authorId,active:!l.following});l.following=!l.following;el.querySelector('.follow').textContent=l.following?'Following':'+ Follow';return;}if(a==='comments')return comments(l);
if(a==='quiz'){modal('A quick check',`<p>${esc(l.question)}</p><div class="quiz-options">${l.options.map((o,i)=>`<button data-answer="${i}">${esc(o)}</button>`).join('')}</div><p id="feedback" class="answer-text"></p>`);$$('[data-answer]').forEach(b=>b.onclick=()=>act(async()=>{const r=await api(`/lessons/${l.id}/quiz`,{answer:Number(b.dataset.answer)});$('#feedback').textContent=(r.correct?'Correct. ':'Not quite. ')+r.rationale;$$('[data-answer]').forEach(b=>b.disabled=true);}));return;}
if(a==='ask'){modal('Ask about this lesson',`<p class="notice">${ai?'AI uses the lesson as context. Check important claims.':'AI is not configured on this server yet.'}</p><form id="ask" class="form"><label>Your question<textarea name="question" required maxlength="1500"></textarea></label><button class="primary" ${ai?'':'disabled'}>Ask Study Media AI</button></form><div id="answer" class="answer-text"></div>`);$('#ask').onsubmit=e=>{e.preventDefault();act(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{$('#answer').textContent='Thinking…';const r=await api('/ai',{mode:'ask',lessonId:l.id,question:new FormData(e.target).get('question')});$('#answer').textContent=r.label+'\n\n'+r.text;}finally{b.disabled=false;}});};}}
async function comments(l,section='all'){const [rows,profile]=await Promise.all([api(`/lessons/${l.id}/comments`),api('/community-role')]);const visible=rows.filter(c=>section==='all'||c.audience===section);modal('Students, teachers & parents',`<div class="comment-tabs"><button data-comment-section="all" class="${section==='all'?'selected':''}">All comments</button><button data-comment-section="teacher" class="${section==='teacher'?'selected':''}">Teacher feedback</button><button data-comment-section="parent" class="${section==='parent'?'selected':''}">Parent feedback</button></div><p class="notice">Comments are visible to people who can access this lesson. Private notes, reflections and individual progress are not included. Parent labels are self-identified and do not establish a link to a child account.</p>${visible.map(c=>`<div class="comment ${c.parent?'reply':''}"><strong>${esc(c.name)}</strong><span class="community-badge">${esc(c.role_label)}</span><p>${esc(c.body)}</p><div class="button-row"><button class="secondary" data-reply="${esc(c.id)}">Reply</button>${c.user_id===me.id||me.admin?`<button class="secondary" data-remove-comment="${esc(c.id)}">Remove</button>`:''}</div></div>`).join('')||'<p>No comments in this section yet.</p>'}<form id="comment" class="form"><label>My community role<select id="comment-role"><option value="student" ${profile.role==='student'?'selected':''}>Student</option><option value="parent" ${profile.role==='parent'?'selected':''}>Parent (self-identified)</option><option value="teacher" ${profile.role==='teacher'?'selected':''}>Teacher (${profile.staffApproved?'posting access approved':profile.reviewedTutor?'reviewed tutor':'self-identified'})</option></select></label><label>Comment section<select name="audience"><option value="discussion">General discussion</option><option value="teacher" ${section==='teacher'?'selected':''}>Teacher feedback</option><option value="parent" ${section==='parent'?'selected':''}>Parent feedback</option></select></label><label id="reply-label">Add your thoughts<textarea name="text" required maxlength="2000" placeholder="Encourage a learner, explain a concept, or suggest a correction…"></textarea></label><button class="primary">Post comment</button></form>`);let parent=null;$$('[data-comment-section]').forEach(b=>b.onclick=()=>act(()=>comments(l,b.dataset.commentSection)));$$('[data-reply]').forEach(b=>b.onclick=()=>{parent=b.dataset.reply;const c=rows.find(c=>c.id===parent);$('#comment [name=audience]').value=c.audience;$('#reply-label').firstChild.textContent='Reply to comment';$('#comment textarea').focus();});$('#comment-role').onchange=e=>act(async()=>{const r=await api('/community-role',{role:e.target.value});toast('Community role: '+r.label);$('#comment [name=audience]').value=r.role==='student'?'discussion':r.role;});$$('[data-remove-comment]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/comments/${b.dataset.removeComment}/remove`,{});comments(l,section);}));$('#comment').onsubmit=e=>{e.preventDefault();act(async()=>{const f=new FormData(e.target);await api(`/lessons/${l.id}/comments`,{text:f.get('text'),audience:f.get('audience'),parent});comments(l,section);});};}

function signupPanel(title){$('#content').innerHTML=`<div class="panel"><h2>${esc(title)}</h2><p>Sign in to save your progress and join the conversation.</p><button id="signup" class="primary">Create an account</button></div>`;$('#signup').onclick=()=>auth();}
async function showPlan(){if(!me)return signupPanel('Your goals. Your pace.');$('#content').innerHTML=`<section class="panel"><h2>Make a plan you can follow.</h2><p>Quiz mistakes help prioritize revision.</p><form id="plan-form" class="form"><label>Subject<select name="subject">${$('#subject').innerHTML.replace('<option value="">All subjects</option>','')}</select></label><label>Days until your goal<input name="days" type="number" min="1" max="90" value="7" required></label><label>Minutes per day<input name="minutes" type="number" min="5" max="120" value="20" required></label><button class="primary">Build my plan</button></form></section><div id="plan"></div>`;const show=p=>{if(!p)return;$('#plan').innerHTML=`<section class="panel"><h2>Your daily path</h2><p>Basic syllabus planner · transparent schedule, not a mastery guarantee.</p>${p.days.map(d=>`<div class="plan-day"><strong>Day ${d.day}</strong><span>${esc(d.activity)}<br>${d.minutes} minutes · ${esc(d.lessons.join(', '))}</span></div>`).join('')}<button id="advice" class="secondary" ${ai?'':'disabled'}>Ask AI for planning advice</button><div id="advice-text" class="answer-text"></div></section>`;$('#advice').onclick=()=>act(async()=>{$('#advice-text').textContent=(await api('/ai',{mode:'plan'})).text;});};show(await api('/plan'));$('#plan-form').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));show(await api('/plan',{...f,days:Number(f.days),minutes:Number(f.minutes)}));});};}
async function showCreator(){if(!me)return signupPanel('Make knowledge worth sharing.');const drafts=await api('/drafts');$('#content').innerHTML=`<section class="panel"><span class="badge">AI ACADEMIC CONTENT CREATOR</span><h2>Your notes. A clearer explanation.</h2><p>Use sources you have permission to share. Drafts need reviewer approval. Published source excerpts are visible to learners.</p><button id="open-my-notes" class="secondary">Choose my saved notes</button><form id="generate" class="form"><label>Subject<input name="subject" value="Statistics" required maxlength="60"></label><label>Topic<input name="topic" required maxlength="100"></label><label>Source notes or transcript<textarea name="source" required maxlength="20000"></textarea></label><label>Import text notes<input id="notes-file" type="file" accept=".txt,text/plain"></label><button class="primary" ${ai?'':'disabled'}>✧ Generate lesson draft</button></form>${ai?'':'<p class="notice">AI generation requires the server Gemini key and model. Manual authoring is available.</p>'}<div class="button-row"><button id="manual" class="secondary">Write a lesson manually</button></div><div id="editor"></div></section><section class="panel"><h2>${me.admin?'Review queue':'Your unpublished drafts'}</h2>${drafts.map(d=>`<div class="plan-day"><strong>${esc(d.title)}</strong><button class="secondary" data-review="${esc(d.id)}">${me.admin?'Review':'View'}</button><button class="secondary" data-edit="${esc(d.id)}">Edit</button></div>`).join('')||'<p>No drafts waiting.</p>'}</section>`;$('#open-my-notes').onclick=()=>render('notes');$('#manual').onclick=()=>editor({title:'',subject:'Statistics',objective:'',slides:[{text:'',narration:''}],example:'',question:'',options:['',''],answer:0,rationale:'',source:''});$('#notes-file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>80000)return toast('Use notes smaller than 80 KB.');$('#generate [name=source]').value=(await f.text()).slice(0,20000);}};$('#generate').onsubmit=e=>{e.preventDefault();act(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{editor((await api('/ai',{mode:'lesson',...Object.fromEntries(new FormData(e.target))})).draft);}finally{b.disabled=false;}});};$$('[data-review]').forEach(b=>b.onclick=()=>{const d=drafts.find(x=>x.id===b.dataset.review);modal(d.title,`<div class="answer-text">${d.slides.map(s=>esc(s.text)+'\n'+esc(s.narration)).join('\n\n')}</div><p>${esc(d.example)}</p><p>${esc(d.question)}</p><p>${d.options.map((o,i)=>`${i===d.answer?'✓ ':''}${esc(o)}`).join('<br>')}</p><p>${esc(d.rationale)}</p><p class="notice">${esc(d.source)}</p>${me.admin?'<button id="publish" class="primary">I checked this lesson · Publish</button>':''}`);if(me.admin)$('#publish').onclick=()=>act(async()=>{await api(`/lessons/${d.id}/publish`,{});$('#dialog').close();toast('Lesson published');showCreator();});});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit]');if(b)act(async()=>{const d=(await api('/drafts')).find(x=>x.id===b.dataset.edit);if(d){editor(d);$('#editor').scrollIntoView({behavior:'smooth'});}});});
function editor(d){$('#editor').innerHTML=`<h3>Edit lesson draft</h3><form id="edit-form" class="form">${['title','subject','objective','example','question','rationale','source'].map(k=>`<label>${esc(k)}<textarea name="${k}" required>${esc(d[k])}</textarea></label>`).join('')}${d.slides.map((s,i)=>`<label>Step ${i+1} writing<input name="s${i}" value="${esc(s.text)}" maxlength="250" required></label><label>Step ${i+1} narration<textarea name="n${i}" required maxlength="1500">${esc(s.narration)}</textarea></label>`).join('')}<label>Answers — one per line<textarea name="options" required>${esc(d.options.join('\n'))}</textarea></label><label>Correct answer number<input name="answer" type="number" min="1" max="4" value="${d.answer+1}" required></label><label>Attach image, video or audio (10 MB maximum)<input id="asset-file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,audio/mpeg,audio/mp4"></label><p class="notice">Videos and audio need a supplied transcript for AI restructuring. Uploading a file does not transcribe it.</p><button class="primary">Save for review</button></form>`;$('#edit-form').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));const upload=$('#asset-file').files[0];if(upload){if(upload.size>10485760)throw Error('Use a file smaller than 10 MB.');const r=await fetch('/api/assets',{method:'POST',headers:{'Content-Type':upload.type,'X-File-Name':encodeURIComponent(upload.name)},body:upload});const a=await r.json();if(!r.ok)throw Error(a.error);d.asset=a.url;d.assetType=upload.type.split('/')[0];}await api(d.id?`/lessons/${d.id}/edit`:'/lessons',{...d,...f,answer:Number(f.answer)-1,options:f.options.split('\n').map(x=>x.trim()).filter(Boolean),slides:d.slides.map((s,i)=>({text:f['s'+i],narration:f['n'+i]}))});toast('Draft saved for review');showCreator();});};}
async function teasers(){const r=await api('/rooms');$('#room-teasers').innerHTML=r.slice(0,3).map(x=>`<button class="room-teaser"><span class="room-badge">◎</span><span><strong>${esc(x.title)}</strong><small>${x.online} online · ${esc(x.subject)}</small></span></button>`).join('');$$('.room-teaser').forEach(b=>b.onclick=()=>render('rooms'));}
async function showRooms(){const rows=await api('/rooms');$('#content').innerHTML=`<section class="panel"><h2>Learn out loud.</h2><p>Chat, talk face to face and sketch ideas together.</p><button id="new-room" class="primary">＋ Create a circle</button></section>${rows.map(r=>`<section class="panel room-panel"><div><span class="badge">${esc(r.subject)}</span><h3>${esc(r.title)}</h3><span class="meta">${r.online} online · ${esc(r.hostName)}</span></div><button class="secondary" data-join="${esc(r.id)}">Join ↗</button></section>`).join('')}`;$$('[data-join]').forEach(b=>b.onclick=()=>act(()=>join(rows.find(r=>r.id===b.dataset.join))));$('#new-room').onclick=()=>{if(!needed())return;modal('Start a study circle','<form id="room-form" class="form"><label>Title<input name="title" required maxlength="100"></label><label>Subject<input name="subject" required maxlength="60"></label><button class="primary">Create circle</button></form>');$('#room-form').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/rooms',Object.fromEntries(new FormData(e.target)));$('#dialog').close();showRooms();teasers();});};}}
function leave(){if(!room)return;room.events?.close();fetch(`/api/rooms/${room.id}/leave`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',keepalive:true}).catch(()=>{});room.stream?.getTracks().forEach(t=>t.stop());for(const p of room.peers.values())p.close();room=null;}
async function join(r){if(!needed())return;leave();stop();const s=room={...r,peers:new Map(),members:[],stream:null,ice:[]};$('#content').innerHTML=`<section class="panel"><span class="badge">LIVE CIRCLE</span><h2>${esc(r.title)}</h2><p>Up to 8 members. No recording.</p><div id="members" class="members"></div><div class="button-row"><button id="audio" class="secondary">Join with voice</button><button id="video" class="secondary">Join with video</button><button id="hand" class="secondary">✋ Raise hand</button><button id="poll" class="secondary">Ask a poll</button><button id="leave" class="secondary">Leave</button></div><p id="call-status" class="notice">Calls need HTTPS and microphone permission.</p><div id="videos" class="video-grid"></div><div id="chat" class="room-chat"></div><form id="chat-form" class="form"><label>Message<input name="text" required maxlength="2000" autocomplete="off"></label><button class="primary">Send</button></form><canvas id="board" width="900" height="400" aria-label="Shared whiteboard"></canvas><div class="button-row"><button id="clear" class="secondary">Clear board · host</button><button id="notes" class="secondary">Save discussion notes</button><button id="room-ai" class="secondary">Invite AI to summarize</button></div></section>`;
const add=m=>{const el=document.createElement('div');el.className='message';const b=document.createElement('b');b.textContent=m.name+': ';el.append(b,document.createTextNode(m.body));$('#chat')?.append(el);if($('#chat'))$('#chat').scrollTop=$('#chat').scrollHeight;};(await api(`/rooms/${r.id}/messages`)).forEach(add);const ice=await api(`/rooms/${r.id}/ice`);s.ice=ice.iceServers;if(!ice.turnConfigured)$('#call-status').textContent='No TURN service is configured; some cross-network calls may not connect. Chat remains available.';
s.events=new CircleEvents(r.id);s.events.onmessage=e=>act(async()=>{if(room!==s)return;const v=JSON.parse(e.data);if(['presence','welcome'].includes(v.type)){const before=new Set(s.members.map(m=>m.id));s.members=v.members;$('#members').innerHTML=v.members.map(m=>`<span class="member">${esc(m.name)}${m.id===me.id?' · you':''}${(r.host===me.id||me.admin)&&m.id!==me.id?` <button data-kick="${esc(m.id)}" aria-label="Remove member">×</button>`:''}</span>`).join('');$$('[data-kick]').forEach(b=>b.onclick=()=>act(()=>api(`/rooms/${r.id}/kick`,{target:b.dataset.kick})));for(const [uid,p]of s.peers)if(!v.members.some(m=>m.id===uid)){p.close();s.peers.delete(uid);document.getElementById('video-'+uid)?.remove();}if(s.stream)for(const m of v.members)if(m.id!==me.id&&!before.has(m.id)&&me.id<m.id)await offer(s,m.id);}
if(v.type==='message')add(v.message);if(v.type==='board'){if(v.clear){const c=$('#board');c.getContext('2d').clearRect(0,0,c.width,c.height);}else draw(v.points);}if(v.type==='signal')await signal(s,v);if(v.type==='removed'){toast('The host removed you from the room.');render('rooms');}});s.events.onerror=()=>{if(room===s){toast('Room disconnected. Join again to continue.');render('rooms');}};
$('#chat-form').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/rooms/${r.id}/messages`,{text:new FormData(e.target).get('text')});e.target.reset();});};$('#leave').onclick=()=>render('rooms');$('#audio').onclick=()=>act(()=>media(s,false));$('#video').onclick=()=>act(()=>media(s,true));$('#hand').onclick=()=>act(()=>api(`/rooms/${r.id}/messages`,{text:'✋ I would like to ask a question.'}));$('#poll').onclick=()=>{modal('Ask the group','<form id="poll-form" class="form"><label>Question<input name="text" required maxlength="400"></label><button class="primary">Post poll</button></form>');$('#poll-form').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/rooms/${r.id}/messages`,{text:'[Poll · answer in chat] '+new FormData(e.target).get('text')});$('#dialog').close();});};};$('#clear').onclick=()=>act(()=>api(`/rooms/${r.id}/board`,{clear:true}));$('#notes').onclick=()=>{const blob=new Blob([r.title+'\n\n'+$('#chat').innerText],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='study-circle-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#room-ai').onclick=()=>{if(!ai)return toast('AI is not configured on this server yet.');act(async()=>{const r=await api('/ai',{mode:'room',roomId:s.id,question:'Summarize the discussion and list unresolved study questions.'});modal(r.label,'<div class="answer-text">'+esc(r.text)+'</div>');});};
const c=$('#board');let point,last=0;const pos=e=>{const b=c.getBoundingClientRect();return[Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))];};c.onpointerdown=e=>{point=pos(e);c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!point||Date.now()-last<100)return;last=Date.now();const next=pos(e),points=[...point,...next];draw(points);point=next;act(()=>api(`/rooms/${r.id}/board`,{points}));};c.onpointerup=c.onpointercancel=()=>point=null;}
function draw(p){const c=$('#board');if(!c)return;const x=c.getContext('2d');x.strokeStyle='#365936';x.lineWidth=3;x.lineCap='round';x.beginPath();x.moveTo(p[0]*c.width,p[1]*c.height);x.lineTo(p[2]*c.width,p[3]*c.height);x.stroke();}
function peer(s,uid){if(s.peers.has(uid))return s.peers.get(uid);const p=new RTCPeerConnection({iceServers:s.ice});s.peers.set(uid,p);s.stream?.getTracks().forEach(t=>p.addTrack(t,s.stream));p.onicecandidate=e=>{if(e.candidate&&room===s)act(()=>api(`/rooms/${s.id}/signal`,{target:uid,kind:'candidate',payload:e.candidate.toJSON()}));};p.ontrack=e=>{let v=document.getElementById('video-'+uid);if(!v){v=document.createElement('video');v.id='video-'+uid;v.autoplay=true;v.playsInline=true;v.controls=true;$('#videos').append(v);}v.srcObject=e.streams[0];v.play().catch(()=>toast('Tap the video to enable sound.'));};return p;}
async function offer(s,uid){const p=peer(s,uid);await p.setLocalDescription(await p.createOffer());await api(`/rooms/${s.id}/signal`,{target:uid,kind:'offer',payload:p.localDescription});}
async function signal(s,e){if(e.kind==='hangup'){s.peers.get(e.from)?.close();s.peers.delete(e.from);return;}const p=peer(s,e.from);if(e.kind==='offer'){if(p.signalingState!=='stable'){if(me.id<e.from)return;await p.setLocalDescription({type:'rollback'});}await p.setRemoteDescription(e.payload);await p.setLocalDescription(await p.createAnswer());await api(`/rooms/${s.id}/signal`,{target:e.from,kind:'answer',payload:p.localDescription});}else if(e.kind==='answer'){if(p.signalingState==='have-local-offer')await p.setRemoteDescription(e.payload);}else if(e.kind==='candidate'){if(p.remoteDescription)await p.addIceCandidate(e.payload);else(p.pendingCandidates??=[]).push(e.payload);}if(p.remoteDescription&&p.pendingCandidates){for(const c of p.pendingCandidates)await p.addIceCandidate(c);p.pendingCandidates=[];}}
async function media(s,video){if(!navigator.mediaDevices?.getUserMedia)throw Error('Voice/video needs HTTPS or localhost.');if(s.stream)throw Error('Leave and rejoin to change the call mode.');s.stream=await navigator.mediaDevices.getUserMedia({audio:true,video});const v=document.createElement('video');v.autoplay=true;v.playsInline=true;v.muted=true;v.srcObject=s.stream;$('#videos').append(v);for(const p of s.peers.values())s.stream.getTracks().forEach(t=>p.addTrack(t,s.stream));for(const m of s.members)if(m.id!==me.id)await offer(s,m.id);$('#call-status').textContent='Microphone active. Leave the circle to stop sharing.';}
async function payments(){const r=await api('/orders');modal('Study pack enquiries',r.instructions?`<p class="answer-text">${esc(r.instructions)}</p><p class="notice">References are pending manual verification, not automatic payment confirmation.</p><form id="order" class="form"><label>Payment or enquiry reference<input name="reference" maxlength="200" required></label><button class="primary">Submit for verification</button></form>${r.orders.map(o=>`<p>${esc(o.reference)} · ${esc(o.status)}</p>`).join('')}`:'<p>Paid study packs are not enabled yet. Explore the available lessons.</p>');if(r.instructions)$('#order').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/orders',Object.fromEntries(new FormData(e.target)));toast('Reference submitted for manual verification');$('#dialog').close();});};}
