function loadedMediaArt(l){const src=esc(l.asset);return l.assetType==='video'?`<video class="lesson-media" src="${src}" preload="none" muted loop playsinline controls></video>`:l.assetType==='audio'?`<audio controls preload="none" src="${src}" class="lesson-audio"></audio>`:`<img class="lesson-media" src="${src}" alt="Lesson illustration" loading="lazy">`;}
class CircleEvents{
 constructor(id){this.id=id;this.cursor=0;this.join=true;this.closed=false;this.timer=setTimeout(()=>this.poll(),0);}
 async poll(){if(this.closed)return;try{const r=await api(`/rooms/${this.id}/events`,{cursor:this.cursor,join:this.join});if(this.closed)return;this.cursor=r.cursor;this.join=false;for(const e of r.events)this.onmessage?.({data:JSON.stringify(e)});this.timer=setTimeout(()=>this.poll(),3000);}catch(e){if(!this.closed)this.onerror?.(e);}}
 close(){this.closed=true;clearTimeout(this.timer);}
}
