const workspaceNav=document.createElement('button');workspaceNav.className='nav';workspaceNav.innerHTML='<span>◇</span> Study workspace';$('.sidebar nav').append(workspaceNav);workspaceNav.onclick=()=>{if(feed.length)act(()=>openWorkspace(feed[0].id));else toast('Open a lesson from the feed first.');};
function workspaceLayout(){leave();stop();clearInterval(tutorClock);clearTimeout(recallTimer);observer?.disconnect();view='workspace';document.body.classList.remove('feed-mode');$('#page-title').textContent='An idea you can work with.';}
async function openWorkspace(lid,action){if(!needed())return;if(!lid)return toast('Choose a published lesson first.');if(action&&$('#workspace-reflection'))await api('/learning/workspace/'+lid,{action:'reflect',reflection:$('#workspace-reflection').value});const w=await api('/learning/workspace/'+lid,action);workspaceLayout();const l=w.lesson,g=w.guidance;$('#content').innerHTML=`<section class="panel workspace-title"><span class="badge">GUIDED STUDY · ${esc(g.state.toUpperCase())}</span><h2>${esc(l.title)}</h2><p>${esc(l.objective)}</p><label>How would you like to work?<select id="workspace-mode"><option value="text" ${w.mode==='text'?'selected':''}>Text and examples</option><option value="voice" ${w.mode==='voice'?'selected':''}>Voice and text</option><option value="visual" ${w.mode==='visual'?'selected':''}>Visual connections</option></select></label><div class="button-row"><button id="workspace-voice" class="secondary">Listen</button><button id="workspace-stop" class="secondary">Stop voice</button><button id="workspace-offline" class="secondary">Save encrypted offline copy</button></div></section><section class="panel"><h2>${esc(g.prompt)}</h2><p>${esc(g.question)}</p>${g.hint?'<p class="notice">Hint: '+esc(g.hint)+'</p>':''}${g.explanation?'<p class="answer-text">'+esc(g.explanation)+'</p>':''}<div class="quiz-options">${['question','hint','practice'].includes(g.state)?g.options.map((o,j)=>`<button data-guided-answer="${j}">${esc(o)}</button>`).join(''):''}</div>${['hint','explanation','review'].includes(g.state)?'<button id="guidance-continue" class="primary">'+(g.state==='explanation'?'Try without the explanation':g.state==='review'?'Practise again':'Show an explanation')+'</button>':''}</section><section class="panel"><h2>Workspace canvas</h2><p>Connect the concept, example and explanation.</p><div id="workspace-graph">${graphSVG(w.graph,l.id)}</div><div class="flashcard-list">${l.slides.map(s=>`<details class="study-flashcard"><summary>${esc(s.text)}</summary><p>${esc(s.narration)}</p></details>`).join('')}</div><h3>Worked example</h3><p class="answer-text">${esc(l.example)}</p>${simulations[l.id]?'<button id="workspace-animation" class="primary">Explore animation</button>':''}<button id="workspace-map" class="secondary">Explore concept relationships</button></section><section class="panel"><h2>Your reflection</h2><p>Explain the relationship in your own words.</p><textarea id="workspace-reflection" maxlength="6000">${esc(w.reflection)}</textarea><button id="save-reflection" class="primary">Save private reflection</button><p class="notice">Practice evidence: ${w.evidence.correct} correct from ${w.evidence.attempts} attempts. ${w.evidence.laterRecallObserved?'A correct answer followed an earlier attempt by at least 24 hours.':'A later recall check has not been observed yet.'} This is not a mastery certification.</p></section>`;if($('#workspace-animation'))$('#workspace-animation').onclick=()=>openLearningAnimation(l.id);$('#workspace-mode').onchange=e=>act(()=>openWorkspace(lid,{action:'mode',mode:e.target.value}));$$('[data-guided-answer]').forEach(b=>b.onclick=()=>act(()=>openWorkspace(lid,{action:'answer',answer:Number(b.dataset.guidedAnswer)})));if($('#guidance-continue'))$('#guidance-continue').onclick=()=>act(()=>openWorkspace(lid,{action:'continue'}));$('#save-reflection').onclick=()=>act(async()=>{await api('/learning/workspace/'+lid,{action:'reflect',reflection:$('#workspace-reflection').value});toast('Private reflection saved.');});$('#workspace-voice').onclick=()=>{if(!('speechSynthesis'in window))return toast('Voice is unavailable; all text remains readable.');stop();const utter=new SpeechSynthesisUtterance(g.prompt+'. '+g.question+'. '+(g.hint||g.explanation||''));utter.rate=.94;speechSynthesis.speak(utter);};$('#workspace-stop').onclick=stop;$('#workspace-map').onclick=()=>act(showKnowledgeMap);$('#workspace-offline').onclick=()=>saveOfflineCopy(lid);if(w.mode==='voice')toast('Tap Listen to hear this step.');if(w.mode==='visual')$('#workspace-graph').scrollIntoView({behavior:'smooth'});}
function graphSVG(graph,focus){let nodes=graph.nodes.filter(n=>n.id===focus||graph.edges.some(e=>(e.from_id===focus&&e.to_id===n.id)||(e.to_id===focus&&e.from_id===n.id)));if(!nodes.length||!focus)nodes=graph.nodes.slice(0,18);const positions=new Map(nodes.map((n,i)=>[n.id,{x:25+(i%3)*220,y:30+Math.floor(i/3)*105}])),height=Math.max(130,Math.ceil(nodes.length/3)*105+25);return `<svg class="concept-canvas" viewBox="0 0 700 ${height}" role="img" aria-label="Concept relationships. Prerequisite arrows show required concepts leading to later concepts."><defs><marker id="concept-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#7f9968"/></marker></defs>${graph.edges.filter(e=>positions.has(e.from_id)&&positions.has(e.to_id)).map(e=>{const a=positions.get(e.from_id),b=positions.get(e.to_id);let sx=a.x+95,sy=a.y+55,tx=b.x+95,ty=b.y-3;if(b.y<a.y){sy=a.y-3;ty=b.y+56;}if(b.y===a.y){sx=b.x>a.x?a.x+191:a.x-2;tx=b.x>a.x?b.x-3:b.x+193;sy=a.y+26;ty=b.y+26;}return `<path d="M${sx} ${sy} Q${(sx+tx)/2} ${(sy+ty)/2-20} ${tx} ${ty}" fill="none" stroke="${e.kind==='prerequisite'?'#73954f':'#adb9a3'}" stroke-width="2" ${e.kind==='prerequisite'?'marker-end="url(#concept-arrow)"':'stroke-dasharray="5 4"'}/>`;}).join('')}${nodes.map(n=>{const p=positions.get(n.id);return `<g><title>${esc(n.label)}: ${esc(n.description)}</title><rect x="${p.x}" y="${p.y}" width="190" height="53" rx="11" fill="${n.id===focus?'#d9e9bc':'#f1f5e9'}" stroke="#c9d8b6"/><text x="${p.x+10}" y="${p.y+31}" font-size="12" fill="#355139">${esc(n.label.length>25?n.label.slice(0,24)+'…':n.label)}</text></g>`;}).join('')}</svg>`;}
async function showKnowledgeMap(){if(!needed())return;const g=await api('/learning/graph');modal('Your connected course',`${graphSVG(g)}<p class="notice">Solid arrows are reviewed prerequisites; dashed lines are other relationships. Only prerequisite links must avoid cycles. Lesson-topic nodes are created from published lessons; more detailed relationships require reviewer input.</p><div class="concept-links">${g.nodes.map(n=>`<button class="connection" data-study-concept="${esc(n.lesson_id)}"><strong>${esc(n.label)}</strong><small>${esc(n.description)}</small></button>`).join('')}</div>${g.edges.map(e=>`<p class="notice">${esc(g.nodes.find(n=>n.id===e.from_id)?.label)} → ${esc(g.nodes.find(n=>n.id===e.to_id)?.label)} · ${esc(e.kind)}<br>${esc(e.evidence)}${me.admin?`<button data-remove-edge="${esc(e.id)}">Remove relationship</button>`:''}</p>`).join('')}${me.admin?`<details><summary>Reviewer: add a concept</summary><form id="concept-node" class="form"><label>Source lesson<select name="lessonId">${[...new Map(g.nodes.map(n=>[n.lesson_id,n])).values()].map(n=>`<option value="${esc(n.lesson_id)}">${esc(n.label)}</option>`).join('')}</select></label><label>Concept label<input name="label" required maxlength="100"></label><label>Meaning or micro-skill<textarea name="description" required maxlength="500"></textarea></label><button class="primary">Add concept</button></form></details><details><summary>Reviewer: add a relationship</summary><form id="concept-edge" class="form"><label>From<select name="from">${g.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('')}</select></label><label>To<select name="to">${g.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('')}</select></label><label>Relationship<select name="kind"><option value="prerequisite">Prerequisite: from is required before to</option><option>related</option><option>application</option><option>example</option></select></label><label>Supporting source or explanation<textarea name="evidence" required maxlength="1000"></textarea></label><button class="primary">Add reviewed relationship</button></form></details>`:''}`);$$('[data-study-concept]').forEach(b=>b.onclick=()=>{$('#dialog').close();act(()=>openWorkspace(b.dataset.studyConcept));});$$('[data-remove-edge]').forEach(b=>b.onclick=()=>act(async()=>{await api('/learning/edges/remove',{id:b.dataset.removeEdge});showKnowledgeMap();}));if($('#concept-node'))$('#concept-node').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/learning/graph',Object.fromEntries(new FormData(e.target)));showKnowledgeMap();});};if($('#concept-edge'))$('#concept-edge').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/learning/edges',Object.fromEntries(new FormData(e.target)));showKnowledgeMap();});};}
function saveOfflineCopy(lid){modal('Encrypt a study copy',`<p>The copy includes this published lesson and its source excerpt. Your full private notes are excluded.</p><form id="encrypt-copy" class="form"><label>Passphrase (10+ characters)<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><label>Repeat passphrase<input name="repeat" type="password" minlength="10" required autocomplete="new-password"></label><button class="primary">Save & download encrypted workspace</button></form><p class="notice">Keep your passphrase. We cannot recover it. The downloaded HTML works separately from the website when you have no connection. Device voice may require a previously installed voice.</p>`);$('#encrypt-copy').onsubmit=e=>{e.preventDefault();act(async()=>{const f=new FormData(e.target),pw=f.get('password');if(pw!==f.get('repeat'))throw Error('Passphrases do not match.');const bundle=await api('/learning/bundle?lessonId='+lid),data={...bundle,events:[],reflection:'',state:'question'},encrypted=await encryptStudy(data,pw);await vaultPut({id:me.id+':'+lid,owner:me.id,...encrypted});saveFile(await encryptedWorkspaceHTML(bundle,pw),'study-media-encrypted-workspace.html','text/html');$('#dialog').close();toast('Encrypted copy saved and downloaded.');});};}
async function showVault(){if(!needed())return;workspaceLayout();const rows=await vaultList(me.id);$('#content').innerHTML=`<section class="panel"><h2>Your encrypted offline study</h2><p>Unlock a device copy or import practice from a downloaded workspace. Private reflections remain encrypted on this device.</p>${rows.map((r,i)=>`<button class="connection" data-unlock-study="${i}">Unlock saved lesson ${i+1}</button>`).join('')||'<p>Open a lesson workspace and choose Save encrypted offline copy.</p>'}<h3>Import offline practice</h3><input id="import-study-events" type="file" accept="application/json,.json"><p class="notice">Sync requires an internet connection and the same signed-in account. Changed lessons need review; conflicting events are retained in the original file.</p></section>`;$$('[data-unlock-study]').forEach(btn=>btn.onclick=()=>{const record=rows[Number(btn.dataset.unlockStudy)];modal('Unlock device copy','<form id="unlock-study" class="form"><label>Passphrase<input name="password" type="password" required></label><button class="primary">Unlock</button></form>');$('#unlock-study').onsubmit=e=>{e.preventDefault();act(async()=>{const pw=new FormData(e.target).get('password'),data=await decryptStudy(record,pw);if(data.owner!==me.id)throw Error('This copy belongs to another account.');activeOffline={record,data,password:pw};$('#dialog').close();renderOfflinePractice();});};});$('#import-study-events').onchange=e=>act(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>200000)throw Error('Use a practice file smaller than 200 KB.');const data=JSON.parse(await f.text());if(data.owner!==me.id)throw Error('Import practice from your own account.');const result=await api('/learning/offline',data);toast(result.events.length+' practice events checked and synced.');});}
function renderOfflinePractice(){const a=activeOffline,l=a.data.lesson,state=a.data.state;workspaceLayout();view='offline-workspace';$('#content').innerHTML=`<section class="panel"><span class="badge">UNLOCKED DEVICE COPY</span><h2>${esc(l.title)}</h2><p>${esc(l.question)}</p>${state==='hint'?'<p class="notice">'+esc(l.example)+'</p>':''}${['explanation','review'].includes(state)?'<p class="answer-text">'+esc(l.rationale)+'</p>':''}<div class="quiz-options">${['question','hint','practice'].includes(state)?l.options.map((o,i)=>`<button data-offline-answer="${i}">${esc(o)}</button>`).join(''):'<button id="offline-continue" class="primary">Continue practice</button>'}</div><p>${a.data.events.length} queued practice events.</p><textarea id="offline-reflection" maxlength="6000" placeholder="Private reflection">${esc(a.data.reflection)}</textarea><div class="button-row"><button id="keep-offline" class="primary">Save encrypted progress</button><button id="sync-offline" class="secondary">Sync practice online</button><button id="lock-offline" class="secondary">Lock copy</button></div><p class="notice">Only quiz choices sync; private reflections stay on this device. Keep this page open while offline or open your downloaded encrypted HTML file.</p></section>`;$$('[data-offline-answer]').forEach(btn=>btn.onclick=()=>act(async()=>{const answer=Number(btn.dataset.offlineAnswer);a.data.reflection=$('#offline-reflection').value;a.data.events.push({eventId:crypto.randomUUID(),lessonId:l.id,revision:l.revision,answer,occurredAt:Date.now()});a.data.state=answer===l.answer?'review':state==='question'?'hint':'explanation';await persistOffline();renderOfflinePractice();}));if($('#offline-continue'))$('#offline-continue').onclick=()=>{a.data.reflection=$('#offline-reflection').value;a.data.state=state==='explanation'?'practice':'question';renderOfflinePractice();};$('#keep-offline').onclick=()=>act(async()=>{a.data.reflection=$('#offline-reflection').value;await persistOffline();toast('Encrypted progress saved.');});$('#sync-offline').onclick=()=>act(syncOffline);$('#lock-offline').onclick=()=>{activeOffline=null;render('vault');};}
async function persistOffline(){const a=activeOffline;if(!a)return;const encrypted=await encryptStudy(a.data,a.password);a.record={id:a.record.id,owner:me.id,...encrypted};await vaultPut(a.record);}
async function syncOffline(){const a=activeOffline;if(!a||a.data.owner!==me.id||!a.data.events.length)return toast('No queued practice to sync.');const result=await api('/learning/offline',{owner:me.id,events:a.data.events.slice(0,50)});const done=new Set(result.events.map(e=>e.eventId));a.data.events=a.data.events.filter(e=>!done.has(e.eventId));await persistOffline();toast(result.events.length+' practice events synced.');if(view==='offline-workspace')renderOfflinePractice();}
window.addEventListener('online',()=>{if(activeOffline?.data.events.length)act(syncOffline);});
let assemblyRefresh=null;const assemblyNav=document.createElement('button');assemblyNav.className='nav';assemblyNav.dataset.view='assembly';assemblyNav.innerHTML='<span>▣</span> Assembly';$('.sidebar nav').append(assemblyNav);assemblyNav.onclick=()=>render('assembly');const assemblyMobile=document.createElement('button');assemblyMobile.textContent='▣';assemblyMobile.setAttribute('aria-label','Assembly and prep');assemblyMobile.onclick=()=>render('assembly');$('.mobile-nav').append(assemblyMobile);
async function showAssembly(){clearInterval(assemblyRefresh);if(!me)return signupPanel('Hear from your teachers.');const [posts,access]=await Promise.all([api('/assembly'),api('/assembly/access')]);$('#content').innerHTML=`<section class="panel"><span class="badge">ASSEMBLY</span><h2>Know what is coming next.</h2><p>Teacher information about upcoming lessons, exams, materials, meetings and timetable changes.</p><label>Show<select id="assembly-filter"><option value="all">All notices</option><option value="prep">Prep / homework</option><option value="upcoming">Upcoming events</option><option value="unread">Unread notices</option></select></label><div class="button-row">${access.canPost?'<button id="new-assembly" class="primary">Post information in advance</button>':`<button id="request-assembly" class="secondary" ${access.status==='pending'?'disabled':''}>${access.status==='pending'?'Teacher access awaiting review':'Request teacher posting access'}</button>`}</div><p class="notice">Notices are visible to everyone with site access, including students and parents. Do not post private student information.</p></section><div id="assembly-posts"></div>${me.admin?`<section class="panel"><h2>Teacher posting access</h2><p>Approve only people you have checked are authorised to make teacher announcements.</p>${access.requests.map(r=>`<div class="note-row"><strong>${esc(r.name)}</strong><p>${esc(r.status)}</p><button class="secondary" data-assembly-teacher="${esc(r.user_id)}" data-status="${r.status==='approved'?'revoked':'approved'}">${r.status==='approved'?'Revoke posting access':'Approve teacher posting access'}</button></div>`).join('')||'<p>No teacher access requests yet.</p>'}</section>`:''}`;function show(){const filter=$('#assembly-filter').value,visible=posts.filter(p=>filter==='all'||filter==='unread'&&!p.is_read||filter==='upcoming'&&p.event_at>Date.now()||filter==='prep'&&p.is_prep);if(filter==='upcoming')visible.sort((a,b)=>a.event_at-b.event_at);$('#assembly-posts').innerHTML=visible.map(p=>`<article class="panel assembly-notice"><span class="badge">${p.publish_at>Date.now()?'SCHEDULED · AUTHOR PREVIEW':p.is_read?'READ':'NEW NOTICE'}</span><h2>${p.is_prep?'Prep: ':''}${esc(p.title)}</h2><small>${esc(p.teacher)}${p.subject?' · '+esc(p.subject):''} · ${new Date(p.publish_at).toLocaleString()}</small>${p.event_at?`<div class="assembly-event">${p.is_prep?'Due:':'For:'} ${new Date(p.event_at).toLocaleString()}</div>`:''}<p class="answer-text">${esc(p.body)}</p><div class="button-row">${p.is_prep&&p.publish_at<=Date.now()?`<button class="primary" data-complete-prep="${esc(p.id)}" data-done="${p.prep_done?'false':'true'}">${p.prep_done?'Marked done · undo':'Mark my prep done'}</button><small>${p.prep_done?'Self-reported completion, not teacher marked.':p.event_at<Date.now()?'Deadline passed':'Not yet marked done'}</small>`:''}${!p.is_read?`<button class="secondary" data-read-assembly="${esc(p.id)}">Mark as read</button>`:''}${p.author===me.id||me.admin?`<button class="secondary" data-withdraw-assembly="${esc(p.id)}">Withdraw notice</button>`:''}</div></article>`).join('')||'<section class="panel"><p>No notices in this view yet.</p></section>';$$('[data-complete-prep]').forEach(b=>b.onclick=()=>act(async()=>{const done=b.dataset.done==='true';await api(`/assembly/${b.dataset.completePrep}/complete`,{done});posts.find(p=>p.id===b.dataset.completePrep).prep_done=done?Date.now():null;show();}));$$('[data-read-assembly]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/assembly/${b.dataset.readAssembly}/read`,{});posts.find(p=>p.id===b.dataset.readAssembly).is_read=1;show();}));$$('[data-withdraw-assembly]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/assembly/${b.dataset.withdrawAssembly}/withdraw`,{});showAssembly();}));}show();assemblyRefresh=setInterval(()=>{if(view!=='assembly'){clearInterval(assemblyRefresh);return;}if(!document.hidden&&!$('#dialog').open)act(showAssembly);},60000);$('#assembly-filter').onchange=show;if($('#request-assembly'))$('#request-assembly').onclick=()=>act(async()=>{await api('/assembly/access',{});showAssembly();});$$('[data-assembly-teacher]').forEach(b=>b.onclick=()=>act(async()=>{await api('/assembly/teachers',{userId:b.dataset.assemblyTeacher,status:b.dataset.status});showAssembly();}));if($('#new-assembly'))$('#new-assembly').onclick=()=>{modal('Information in advance','<form id="assembly-form" class="form"><label>Type<select name="kind"><option value="notice">Teacher notice</option><option value="prep">Prep / homework assignment</option></select></label><label>Title<input name="title" required maxlength="150" placeholder="Bring your statistics exercises on Monday"></label><label>Subject or group (required for prep)<input name="subject" maxlength="60"></label><label>Information or prep instructions<textarea name="body" required maxlength="6000" placeholder="Explain what students and parents need to know or prepare."></textarea></label><label>Publish later (optional, your device timezone)<input name="publish" type="datetime-local"></label><label>Event or prep deadline (required for prep, your device timezone)<input name="event" type="datetime-local"></label><button class="primary">Post teacher notice</button></form><p class="notice">Leave publication time blank to publish now. A scheduled notice stays hidden from other users until that time. This board does not send email or push alerts.</p>');$('#assembly-form [name=kind]').onchange=e=>{const prep=e.target.value==='prep';$('#assembly-form [name=subject]').required=prep;$('#assembly-form [name=event]').required=prep;};$('#assembly-form').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));await api('/assembly',{kind:f.kind,title:f.title,body:f.body,subject:f.subject,publishAt:f.publish?new Date(f.publish).getTime():Date.now(),eventAt:f.event?new Date(f.event).getTime():null});$('#dialog').close();showAssembly();});};};}
const rewardsNav=document.createElement('button');rewardsNav.className='nav';rewardsNav.dataset.view='rewards';rewardsNav.innerHTML='<span>☆</span> Student rewards';$('.sidebar nav').append(rewardsNav);rewardsNav.onclick=()=>render('rewards');
async function showRewards(){if(!me)return signupPanel('Be recognised for showing up to learn.');const campaigns=await api('/rewards');$('#content').innerHTML=`<section class="panel rewards-intro"><span class="badge">FROM THE APP COMPANY</span><h2>Show up. Learn. Be recognised.</h2><p>Join an announced company-funded student reward campaign. Build consistent practice across different lessons.</p><p class="notice">Campaigns state their prizes, dates and rules in advance. Watching, liking and repeating the same answer do not produce unlimited points. Activity scores guide company review; they do not certify understanding or guarantee a prize.</p>${me.admin?'<button id="new-reward" class="primary">Set up a company reward campaign</button>':''}</section>${campaigns.map(c=>`<section class="panel reward-campaign"><span class="badge">${c.status==='draft'?'COMPANY DRAFT':Date.now()>c.end_at?'ENDED · COMPANY REVIEW':Date.now()<c.start_at?'UPCOMING':'OPEN FOR STUDENTS'}</span><h2>${esc(c.title)}</h2><p class="reward-prize">☆ ${esc(c.prize)}</p><p>${c.quantity} prize${c.quantity===1?'':'s'} · Provided by the app company</p><small>${new Date(c.start_at).toLocaleString()} → ${new Date(c.end_at).toLocaleString()}</small><div class="button-row"><button class="primary" data-reward-campaign="${esc(c.id)}">Rules, my activity & rewards</button>${me.admin&&c.status==='draft'?`<button class="secondary" data-open-reward="${esc(c.id)}">Confirm funded prizes & open</button>`:''}</div></section>`).join('')||'<section class="panel"><p>No company-funded reward campaigns have been announced yet.</p></section>'}`;$$('[data-reward-campaign]').forEach(b=>b.onclick=()=>act(()=>rewardDetails(b.dataset.rewardCampaign)));$$('[data-open-reward]').forEach(b=>b.onclick=()=>{modal('Confirm company funding','<p>Open this campaign only after the company has secured the announced prizes and can fulfil the published terms.</p><form id="funded-reward" class="form"><label class="toggle-row"><input type="checkbox" required>The company has funded the prizes and fulfilment</label><button class="primary">Open campaign to students</button></form>');$('#funded-reward').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/rewards/${b.dataset.openReward}/activate`,{funded:true});$('#dialog').close();showRewards();});};});if($('#new-reward'))$('#new-reward').onclick=()=>{modal('Company reward campaign','<form id="reward-campaign" class="form"><label>Campaign name<input name="title" required maxlength="100"></label><label>Actual prize and what is included<textarea name="prize" required maxlength="1500" placeholder="Describe prizes the company will fund. Do not promise unconfirmed items."></textarea></label><label>Number of prizes<input name="quantity" type="number" min="1" max="100" required></label><label>Starts (your device timezone)<input name="start" type="datetime-local" required></label><label>Ends (your device timezone)<input name="end" type="datetime-local" required></label><label>Eligibility, selection and delivery terms<textarea name="terms" required maxlength="3000" placeholder="State eligibility, how activity will be reviewed, tie handling, fulfilment timing and how recipients will be contacted in the app."></textarea></label><button class="primary">Save company draft</button></form>');$('#reward-campaign').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));await api('/rewards',{title:f.title,prize:f.prize,quantity:Number(f.quantity),startAt:new Date(f.start).getTime(),endAt:new Date(f.end).getTime(),terms:f.terms});$('#dialog').close();showRewards();});};};}
async function rewardDetails(cid){const r=await api('/rewards/'+cid),c=r.campaign,ended=Date.now()>=c.end_at;modal(c.title,`<p class="reward-prize">☆ ${esc(c.prize)}</p><p>${c.quantity} company-funded prize${c.quantity===1?'':'s'}. ${new Date(c.start_at).toLocaleString()} → ${new Date(c.end_at).toLocaleString()}</p><p class="answer-text">${esc(c.terms)}</p><p class="notice">${esc(r.rules)}</p>${r.mine?`<div class="reward-score"><strong>${r.mine.score} points</strong><span>${r.mine.correctLessons} different lessons answered correctly · ${r.mine.activeDays} active practice days</span><small>Your current activity position: ${r.mine.rank} of ${r.participants} participants. Final awards require company review.</small></div>`:!me.admin&&c.status==='open'&&Date.now()>=c.start_at&&!ended?'<form id="join-reward" class="form"><label class="toggle-row"><input name="accepted" type="checkbox" required>I am a student and accept these campaign rules and review process</label><label class="toggle-row"><input name="public" type="checkbox">Show my chosen display name on the campaign board (optional)</label><label>Display name if showing publicly<input name="alias" maxlength="30" placeholder="Choose an alias, not contact details"></label><button class="primary">Join student campaign</button></form>':'<p>This campaign is not open for new participation now.</p>'}<h3>Opt-in campaign board</h3>${r.board.map(p=>`<div class="reward-board"><strong>${p.rank}. ${esc(p.alias)}</strong><span>${p.score} points</span></div>`).join('')||'<p>No participants have chosen public display yet. Private participants are omitted.</p>'}${r.awards.length?'<h3>'+ (me.admin?'Company award records':'Your reward')+'</h3>':''}${r.awards.map(a=>`<div class="panel"><strong>${me.admin?esc(a.student_name)+' · ':''}${esc(a.status==='selected'?'Selected · awaiting company delivery':'Delivered')}</strong><p>${esc(a.reason)}</p>${a.reference?'<p class="notice">Delivery record: '+esc(a.reference)+'</p>':''}${me.admin&&a.status==='selected'?`<button class="secondary" data-deliver-reward="${esc(a.id)}">Record actual prize delivery</button>`:''}</div>`).join('')}${me.admin?`<h3>Company review</h3><p>Verify student eligibility and activity before selecting recipients. Only the announced number of prizes can be allocated.</p>${r.review.map(p=>`<div class="note-row"><strong>${esc(p.student_name)}</strong><p>${p.score} points · ${p.correct_lessons} distinct correct lessons · ${p.active_days} active days</p>${ended&&p.score>0?`<button class="secondary" data-award-student="${esc(p.user_id)}">Review & select recipient</button>`:''}</div>`).join('')||'<p>No participating students yet.</p>'}`:''}`);
if($('#join-reward'))$('#join-reward').onsubmit=e=>{e.preventDefault();act(async()=>{const f=new FormData(e.target);await api(`/rewards/${cid}/join`,{accepted:f.has('accepted'),public:f.has('public'),alias:f.get('alias')});rewardDetails(cid);});};$$('[data-award-student]').forEach(b=>b.onclick=()=>{modal('Company award review','<form id="award-student" class="form"><label>Selection reason and eligibility review<textarea name="reason" required maxlength="1000"></textarea></label><label class="toggle-row"><input type="checkbox" required>I verified student eligibility and reviewed the activity</label><button class="primary">Allocate one announced prize</button></form>');$('#award-student').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/rewards/${cid}/award`,{userId:b.dataset.awardStudent,reviewed:true,reason:new FormData(e.target).get('reason')});rewardDetails(cid);});};});$$('[data-deliver-reward]').forEach(b=>b.onclick=()=>{modal('Record company prize delivery','<form id="deliver-reward" class="form"><label>Delivery reference or receipt<input name="reference" required maxlength="300"></label><label class="toggle-row"><input type="checkbox" required>The company has actually delivered this prize</label><button class="primary">Mark delivered</button></form>');$('#deliver-reward').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/rewards/${cid}/deliver`,{awardId:b.dataset.deliverReward,delivered:true,reference:new FormData(e.target).get('reference')});rewardDetails(cid);});};});}
const schoolNav=document.createElement('button');schoolNav.className='nav';schoolNav.innerHTML='<span>⌂</span> My school & classes';$('.sidebar nav').prepend(schoolNav);schoolNav.onclick=()=>render('schools');
async function showSchools(){if(!me)return signupPanel('Connect with your school.');const schools=await api('/schools');$('#content').innerHTML=`<section class="panel"><span class="badge">SCHOOL COMMUNITIES</span><h2>Your school life, connected.</h2><p>Join your class as a student, teacher or parent. School managers check membership before class information becomes visible.</p><button id="register-school" class="primary">Request a school space</button><p class="notice">School spaces require platform review. Parent membership grants only the class's shared information; it does not link a child account or reveal private notes, reflections or practice results.</p></section>${schools.map(s=>`<section class="panel"><span class="badge">${s.status==='approved'?'PLATFORM REVIEWED':esc(s.status.toUpperCase())}</span><h2>${esc(s.name)}</h2><p>${esc(s.country)} · ${esc(s.description)}</p><button class="primary" data-open-school="${esc(s.id)}">Open school space</button></section>`).join('')||'<section class="panel"><p>No school spaces yet. A school manager can request one for review.</p></section>'}`;$$('[data-open-school]').forEach(b=>b.onclick=()=>act(()=>showSchool(b.dataset.openSchool)));$('#register-school').onclick=()=>{modal('Request a school space','<form id="school-request" class="form"><label>School name<input name="name" required maxlength="150"></label><label>Country or location<input name="country" required maxlength="80"></label><label>School description and your role<textarea name="description" required maxlength="1500"></textarea></label><button class="primary">Submit for platform review</button></form><p class="notice">The requesting account becomes the space manager only after platform approval. No other school or class access is granted.</p>');$('#school-request').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/schools',Object.fromEntries(new FormData(e.target)));$('#dialog').close();showSchools();});};};}
async function showSchool(sid){const d=await api('/schools/'+sid),s=d.school;leave();stop();clearInterval(tutorClock);observer?.disconnect();view='schools';document.body.classList.remove('feed-mode');$('#content').innerHTML=`<section class="panel"><span class="badge">${s.status==='approved'?'PLATFORM REVIEWED SCHOOL':esc(s.status)}</span><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p><div class="button-row"><button id="schools-back" class="secondary">All schools</button>${s.status==='approved'?'<button id="school-assembly" class="primary">School Assembly</button>':''}${d.canManage&&s.status==='approved'?'<button id="new-school-class" class="secondary">Create a class</button>':''}${me.admin?'<button id="review-school" class="secondary">Platform school review</button>':''}</div></section><section class="panel"><h2>Classes & subjects</h2>${d.classes.map(c=>{const m=d.mine.find(m=>m.class_id===c.id);return `<div class="note-row"><strong>${esc(c.name)}</strong><p>${esc(c.subject)}${m?' · '+esc(m.role)+' · '+esc(m.status):''}</p>${d.canManage||m?.status==='approved'?`<button class="primary" data-class-space="${esc(c.id)}">Open my class</button>`:m?'<small>Membership requires school-manager approval.</small>':`<button class="secondary" data-join-class="${esc(c.id)}">Request membership</button>`}</div>`;}).join('')||'<p>No classes have been created yet.</p>'}</section>${d.canManage?`<section class="panel"><h2>Membership approval</h2><p>Check the person and requested role before granting access to class information.</p>${d.requests.map(m=>`<div class="note-row"><strong>${esc(m.user_name)}</strong><p>${esc(m.class_name)} · ${esc(m.role)} · ${esc(m.status)}</p><button class="secondary" data-school-member="${esc(m.id)}" data-status="${m.status==='approved'?'revoked':'approved'}">${m.status==='approved'?'Revoke class access':'Review & approve membership'}</button></div>`).join('')||'<p>No membership requests.</p>'}</section>`:''}`;$('#schools-back').onclick=showSchools;if($('#school-assembly'))$('#school-assembly').onclick=()=>act(()=>showClassSpace(sid,''));if($('#review-school'))$('#review-school').onclick=()=>{modal('Platform review: '+s.name,'<form id="school-review" class="form"><label>Checks performed<textarea name="note" required maxlength="1500" placeholder="Record how the school and manager were checked. Do not include private identity documents."></textarea></label><label>Decision<select name="status"><option value="approved">Approve school space</option><option value="rejected">Reject / close access</option></select></label><label class="toggle-row"><input type="checkbox" required>I checked this school and the manager’s authority</label><button class="primary">Record platform review</button></form>');$('#school-review').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/schools/${sid}/review`,{...Object.fromEntries(new FormData(e.target)),reviewed:true});$('#dialog').close();showSchool(sid);});};};if($('#new-school-class'))$('#new-school-class').onclick=()=>{modal('Create a school class','<form id="school-class" class="form"><label>Class or group name<input name="name" required maxlength="100" placeholder="Senior 2 A"></label><label>Subject<input name="subject" required maxlength="60" placeholder="Mathematics"></label><button class="primary">Create class</button></form>');$('#school-class').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/schools/${sid}/classes`,Object.fromEntries(new FormData(e.target)));$('#dialog').close();showSchool(sid);});};};$$('[data-class-space]').forEach(b=>b.onclick=()=>act(()=>showClassSpace(sid,b.dataset.classSpace)));$$('[data-join-class]').forEach(b=>b.onclick=()=>{modal('Request class membership','<form id="join-school-class" class="form"><label>Your role<select name="role"><option value="student">Student</option><option value="teacher">Teacher</option><option value="parent">Parent</option></select></label><button class="primary">Request school-manager approval</button></form>');$('#join-school-class').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/schools/${sid}/join`,{classId:b.dataset.joinClass,role:new FormData(e.target).get('role')});$('#dialog').close();showSchool(sid);});};});$$('[data-school-member]').forEach(b=>b.onclick=()=>{modal('Review class access',`<form id="review-class-member" class="form"><p>${b.dataset.status==='approved'?'Check the person, class and requested role. Parent access is to shared class information only.':'Revocation prevents further access to this class.'}</p><label class="toggle-row"><input type="checkbox" required>I checked this membership decision</label><button class="primary">Confirm ${esc(b.dataset.status)}</button></form>`);$('#review-class-member').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/schools/${sid}/members`,{id:b.dataset.schoolMember,status:b.dataset.status,checked:true});$('#dialog').close();showSchool(sid);});};});}
async function showClassSpace(sid,cid){const [d,posts]=await Promise.all([api('/schools/'+sid),api(`/schools/${sid}/posts?classId=`+encodeURIComponent(cid))]),c=d.classes.find(c=>c.id===cid),m=d.mine.find(m=>m.class_id===cid),role=d.canManage?'school_manager':m?.role,canTeach=d.canManage||role==='teacher';view='schools';$('#content').innerHTML=`<section class="panel"><span class="badge">${cid?'PRIVATE CLASS SPACE':'SCHOOL ASSEMBLY'}</span><h2>${esc(c?c.name:d.school.name)}</h2><p>${esc(c?.subject||'School-wide notices for approved members')}</p><div class="button-row"><button id="class-back" class="secondary">Back to school</button>${canTeach?'<button id="class-teacher-post" class="primary">Teacher notice / prep</button>':''}${cid?'<button id="class-discussion" class="secondary">Start a class discussion</button>':''}</div><p class="notice">Only approved members can read this space. Shared class posts are separate from personal notes and private practice records.</p></section>${posts.map(p=>`<article class="panel"><span class="badge">${esc(p.kind.toUpperCase())}${p.class_id?'':' · SCHOOL ASSEMBLY'}</span><h2>${esc(p.title)}</h2><small>${esc(p.author_name)} · ${esc(p.role.replaceAll('_',' '))} · ${new Date(p.created).toLocaleString()}</small><p class="answer-text">${esc(p.body)}</p>${p.due_at?'<p class="assembly-event">Due: '+new Date(p.due_at).toLocaleString()+'</p>':''}<div class="button-row">${p.lesson_id?`<button class="secondary" data-school-lesson="${esc(p.lesson_id)}">Open linked lesson</button>`:''}${p.kind==='prep'&&role==='student'?`<button class="primary" data-school-prep="${esc(p.id)}" data-done="${p.my_done?'false':'true'}">${p.my_done?'Marked done · undo':'Mark my prep done'}</button>`:''}${p.author===me.id||d.canManage?`<button class="secondary" data-school-withdraw="${esc(p.id)}">Withdraw post</button>`:''}</div></article>`).join('')||'<section class="panel"><p>No posts in this space yet.</p></section>'}`;$('#class-back').onclick=()=>showSchool(sid);function compose(discussion){modal(discussion?'Class discussion':'Teacher notice / prep',`<form id="class-post" class="form">${discussion?'<input type="hidden" name="kind" value="discussion">':`<label>Type<select name="kind"><option value="notice">Notice / Assembly</option>${cid?'<option value="prep">Prep / homework</option>':''}</select></label>`}<label>Title<input name="title" required maxlength="150"></label><label>Message or instructions<textarea name="body" required maxlength="6000"></textarea></label><label>Prep due date (required for prep)<input name="due" type="datetime-local"></label><label>Published lesson ID (optional)<input name="lessonId" maxlength="60" placeholder="For example: cells"></label><button class="primary">Post to this space</button></form>`);$('#class-post').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));await api(`/schools/${sid}/posts`,{...f,classId:cid,dueAt:f.due?new Date(f.due).getTime():null});$('#dialog').close();showClassSpace(sid,cid);});};}if($('#class-teacher-post'))$('#class-teacher-post').onclick=()=>compose(false);if($('#class-discussion'))$('#class-discussion').onclick=()=>compose(true);$$('[data-school-lesson]').forEach(b=>b.onclick=()=>act(()=>openWorkspace(b.dataset.schoolLesson)));$$('[data-school-prep]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/school-posts/${b.dataset.schoolPrep}/done`,{done:b.dataset.done==='true'});showClassSpace(sid,cid);}));$$('[data-school-withdraw]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/school-posts/${b.dataset.schoolWithdraw}/withdraw`,{});showClassSpace(sid,cid);}));}
window.addEventListener('pagehide',()=>{leave();stop();});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();clearTimeout(recallTimer);}});await act(async()=>{await refresh();await subjects();await render();await teasers();});


function openLearningAnimation(id){modal("Explore a learning animation",'<div id="learning-animation-root"></div>');mountAnimation($("#learning-animation-root"),id);}
const animationNav=document.createElement("button");animationNav.className="nav";animationNav.innerHTML="<span>▷</span> Learning animations";$(".sidebar nav").append(animationNav);animationNav.onclick=()=>openLearningAnimation();
